def import_legacy_data_once():
    con = sqlite3.connect(DB_PATH)
    try:
        con.execute("""
            CREATE TABLE IF NOT EXISTS legacy_import_meta (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL
            )
        """)

        done = con.execute(
            "SELECT value FROM legacy_import_meta WHERE key = ?",
            ("old_bothost_backup_2026_10_26",),
        ).fetchone()

        if done:
            print("Legacy DB import: already completed.")
            return

        imported = 0

        # Все основные таблицы уже созданы init_* функциями в main.py.
        # Здесь переносим только строки данных, не подменяя сам SQLite-файл.
        for table, rows in LEGACY_DATA.items():
            exists = con.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",
                (table,),
            ).fetchone()
            if not exists:
                print(f"Legacy DB import: table {table} does not exist in current schema, skipped.")
                continue

            current_columns = {
                row[1]
                for row in con.execute(f'PRAGMA table_info("{table}")')
            }

            for row in rows:
                filtered = {k: v for k, v in row.items() if k in current_columns}
                if not filtered:
                    continue

                columns = list(filtered.keys())
                placeholders = ",".join("?" for _ in columns)
                quoted_columns = ",".join(f'"{c}"' for c in columns)

                con.execute(
                    f'INSERT OR REPLACE INTO "{table}" ({quoted_columns}) '
                    f'VALUES ({placeholders})',
                    [filtered[c] for c in columns],
                )
                imported += 1

        con.execute(
            "INSERT OR REPLACE INTO legacy_import_meta(key, value) VALUES (?, ?)",
            ("old_bothost_backup_2026_10_26", "done"),
        )
        con.commit()

        result = con.execute("PRAGMA quick_check").fetchone()
        if not result or result[0] != "ok":
            raise RuntimeError(f"SQLite quick_check failed after import: {result}")

        print(f"✅ Legacy DB import completed: {imported} rows restored.")
    finally:
        con.close()
